import "dotenv/config";

process.on("uncaughtException", (err) => {
  console.error("[fatal] uncaughtException:", err.message, err.stack);
  process.exit(1);
});
process.on("unhandledRejection", (err) => {
  console.error("[fatal] unhandledRejection:", err);
  process.exit(1);
});

import express from "express";
import session from "express-session";
import multer from "multer";
import path from "path";
import fs from "fs";
import { fileURLToPath } from "url";

import { ensureSchema, ensureBootstrapUser } from "./db.js";
import { autoMigrateIfNeeded } from "./autoMigrate.js";
import authRoutes from "./routes/auth.js";
import orderRoutes from "./routes/orders.js";
import priceRoutes from "./routes/price.js";
import kaspiRoutes from "./routes/kaspi.js";
import catalogRoutes from "./routes/catalog.js";
import counterRoutes from "./routes/counters.js";
import employeeRoutes from "./routes/employees.js";
import companiesRoutes from "./routes/companies.js";
import pricePdfRoutes from "./routes/pricePdf.js";
import productionRoutes from "./routes/production.js";
import metaRoutes from "./routes/meta.js";
import settingsRoutes from "./routes/settings.js";
import auditRoutes from "./routes/audit.js";
import * as authMiddleware from "./middleware/auth.js";

// Если middleware/auth.js остался старой версии, в нём нет requirePermission.
// Раньше это роняло весь сервер на старте — теперь просто предупреждаем,
// а проверка прав временно пропускает всех авторизованных.
const requireAuth = authMiddleware.requireAuth;
const requirePermission = authMiddleware.requirePermission || function () {
  console.warn("[!] middleware/auth.js устарел: нет requirePermission. Разделы открыты всем, кто вошёл. Обновите файл.");
  return (req, res, next) => (req.session && req.session.userId ? next() : res.status(401).json({ error: "not_authenticated" }));
};

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const UPLOAD_DIR = process.env.UPLOAD_DIR || path.join(__dirname, "uploads");
if (!fs.existsSync(UPLOAD_DIR)) fs.mkdirSync(UPLOAD_DIR, { recursive: true });

const app = express();
app.set("trust proxy", 1);

app.use(express.json({ limit: "5mb" }));

app.use(session({
  secret: process.env.SESSION_SECRET || "dev-secret-change-me",
  resave: false,
  saveUninitialized: false,
  cookie: {
    maxAge: 1000 * 60 * 60 * 24 * 7, // 7 дней
    secure: process.env.NODE_ENV === "production",
    sameSite: "lax"
  }
}));

// Загрузка фото
const upload = multer({
  storage: multer.diskStorage({
    destination: UPLOAD_DIR,
    filename: (req, file, cb) => {
      const ext = path.extname(file.originalname) || ".jpg";
      cb(null, Date.now() + "_" + Math.random().toString(36).slice(2, 8) + ext);
    }
  }),
  limits: { fileSize: 8 * 1024 * 1024 },
  fileFilter: (req, file, cb) => {
    const okTypes = ["image/jpeg", "image/png", "image/webp", "image/gif"];
    if (!okTypes.includes(file.mimetype)) return cb(new Error("Разрешены только изображения (jpg/png/webp/gif)"));
    cb(null, true);
  }
});
app.post("/api/upload", requireAuth, (req, res) => {
  upload.single("photo")(req, res, (err) => {
    if (err) return res.status(400).json({ error: "upload_failed", message: err.message });
    if (!req.file) return res.status(400).json({ error: "no_file" });
    res.json({ path: "/uploads/" + req.file.filename });
  });
});
app.use("/uploads", express.static(UPLOAD_DIR));

// API маршруты
app.use("/api/auth", authRoutes);
app.use("/api/orders", orderRoutes);
app.use("/api/price", priceRoutes);
app.use("/api/kaspi", kaspiRoutes);
app.use("/api/catalog", catalogRoutes);
app.use("/api/counters", counterRoutes);
app.use("/api/employees", employeeRoutes);
app.use("/api/companies", companiesRoutes);
app.use("/api/price-pdf", requirePermission("price"), pricePdfRoutes);
app.use("/api/production", productionRoutes);
app.use("/api/meta", metaRoutes);
app.use("/api/settings", requirePermission("kaspi"), settingsRoutes);
app.use("/api/audit", requirePermission("audit"), auditRoutes);

// Подключаем модули по одному: если какой-то файл не залит на сервер,
// упадёт только он, а остальная программа продолжит работать.
// Раньше один недостающий файл убивал весь сервис на старте.
async function mountRoute(name, mountPath, guard) {
  try {
    const mod = await import(`./routes/${name}.js`);
    if (guard) app.use(mountPath, guard, mod.default);
    else app.use(mountPath, mod.default);
  } catch (e) {
    console.error(`[!] Раздел ${mountPath} не подключён: ${e.message}`);
    app.use(mountPath, (req, res) => res.status(503).json({
      error: "module_missing",
      message: `Этот раздел не установлен на сервере (нет файла routes/${name}.js). Залейте файл и перезапустите.`
    }));
  }
}

await mountRoute("priceLists", "/api/price-lists", requirePermission("price"));
await mountRoute("chinaPurchases", "/api/china-purchases", requirePermission("china"));
await mountRoute("chinaStock", "/api/china-stock", requirePermission("china"));
await mountRoute("payroll", "/api/payroll", requirePermission("salary"));
await mountRoute("tasks", "/api/tasks", null);
await mountRoute("monitor", "/api/monitor", null);
await mountRoute("dispatch", "/api/dispatch", null);
await mountRoute("backup", "/api/backup", null);
await mountRoute("legacyImport", "/api/legacy-import", null);
await mountRoute("stats", "/api/stats", null);

// Иконки приложения. Нужны именно PNG и ICO: Windows для ярлыка на рабочем
// столе и Chrome для установки SVG-иконку не берут — получается белый лист.
const ICON_PNG_192 = Buffer.from("", "base64");
const ICON_PNG_512 = Buffer.from("", "base64");
const ICON_ICO = Buffer.from("", "base64");
const ICON_SVG = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512">
  <rect width="512" height="512" rx="96" fill="#0F172A"/>
  <text x="50%" y="47%" text-anchor="middle" dominant-baseline="middle"
        font-family="Arial Black, Arial, sans-serif" font-size="205" font-weight="900" fill="#FFFFFF">PFS</text>
  <rect x="169" y="358" width="174" height="28" rx="14" fill="#F59E0B"/>
</svg>`;

function sendIcon(res, body, type) {
  res.setHeader("Content-Type", type);
  res.setHeader("Cache-Control", "public, max-age=604800");
  res.send(body);
}
app.get("/favicon.ico", (req, res) => sendIcon(res, ICON_ICO, "image/x-icon"));
app.get("/icon-192.png", (req, res) => sendIcon(res, ICON_PNG_192, "image/png"));
app.get("/icon-512.png", (req, res) => sendIcon(res, ICON_PNG_512, "image/png"));
app.get("/apple-touch-icon.png", (req, res) => sendIcon(res, ICON_PNG_192, "image/png"));
app.get("/apple-touch-icon-precomposed.png", (req, res) => sendIcon(res, ICON_PNG_192, "image/png"));
app.get("/icon.svg", (req, res) => sendIcon(res, ICON_SVG, "image/svg+xml"));

app.get("/manifest.webmanifest", (req, res) => {
  res.setHeader("Content-Type", "application/manifest+json");
  res.json({
    name: "PFS Control — учёт заказов",
    short_name: "PFS Control",
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: "#0F172A",
    theme_color: "#0F172A",
    icons: [
      { src: "/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" }
    ]
  });
});

// Статика фронтенда
app.use(express.static(path.join(__dirname, "public")));
app.get("/*splat", (req, res) => {
  res.sendFile(path.join(__dirname, "public", "index.html"));
});

const PORT = process.env.PORT || 3000;

ensureSchema();

// Автоперенос старых данных (data.json -> SQLite), если найдём файл и БД ещё пустая.
// Работает без Shell — специально для бесплатного тарифа Render, где консоль недоступна.
const oldDataCandidates = [
  process.env.DB_PATH ? path.join(path.dirname(process.env.DB_PATH), "data.json") : null,
  path.join(__dirname, "data.json")
].filter(Boolean);
let migrated = false;
for (const candidate of oldDataCandidates) {
  const result = autoMigrateIfNeeded(candidate);
  if (result.ran) { migrated = true; break; }
}
ensureBootstrapUser(); // на случай, если старого data.json не нашлось — создаст admin/admin

// Сброс пароля админа без доступа к консоли — если задана переменная окружения
// RESET_ADMIN_PASSWORD, принудительно установим её как пароль пользователя
// ADMIN_USER (или 'admin', если не задан). После успешного входа переменную
// со сброшенным паролем стоит убрать из Environment на хостинге.
if (process.env.RESET_ADMIN_PASSWORD) {
  const bcrypt = (await import("bcryptjs")).default;
  const { db } = await import("./db.js");
  const username = process.env.ADMIN_USER || "admin";
  const hash = bcrypt.hashSync(process.env.RESET_ADMIN_PASSWORD, 10);
  const result = db.prepare("UPDATE users SET password_hash = ? WHERE username = ?").run(hash, username);
  if (result.changes > 0) {
    console.log(`[reset] Пароль пользователя "${username}" сброшен через RESET_ADMIN_PASSWORD`);
  } else {
    console.log(`[reset] Пользователь "${username}" не найден — пароль не сброшен`);
  }
}

app.listen(PORT, () => {
  console.log(`Сервер запущен: http://localhost:${PORT}`);
});
